        SwiftReservationCategory::State,
        header,
        self.cursor,
        Some(self.wasi.usage()),
    )?);
    macro_rules! arena {
        ($field:ident, $index:literal, $capacity:expr) => {{
            partial.state.buffers[$index] = Some(self.control.admit_with_wasi(
                SwiftReservationCategory::State,
                requests[$index],
                self.cursor,
                Some(self.wasi.usage()),
            )?);
            self.reserve(&mut partial.state.$field, $capacity)?;
